from docbuild import *
d = new_doc(spacing=1.2, footer=False)
TITLE(d, "Pre-submission enquiry: Nature Machine Intelligence", size=14)
P(d, "**Proposed title:** Detecting machine-written scholarly text depends on the generator and on what authors know", indent=False, after=6)
P(d, "**Article type:** Article", indent=False, after=6)
P(d, "**Corresponding author:** [name, affiliation, email]", indent=False, after=10)
H2(d, "Summary (about 250 words)")
P(d, "Publishers, preprint servers and research-integrity offices must decide how much to spend screening documents for machine authorship, yet detection research reports accuracy for one generator at a time, without base rates, costs or adaptive authors. We study cascaded screening, in which a free screen built from counts of seven small linguistic events (parentheses, semicolons, passives and others) decides which documents reach a costly language-model judge. We model the events as a doubly stochastic Poisson process and add scale-dependent clustering features, and we evaluate on [N] human papers (2015 to 2019, medicine and computer science) and papers written by GPT-4o, Claude and Llama.", indent=False, align="justify")
P(d, "Four findings stand out. Screens detect machine papers well only within a generator (AUC 0.99 within GPT-4o, 0.73 when trained on GPT-4o and tested on Claude, near chance when trained on human text alone). A strong judge (Gemini 2.5 Pro, AUC 0.97 on two generators) almost completely misses a third (AUC 0.66). A cascade keeps most of the judge's detection at lower cost when machine papers are rare. A crude feature-aware edit cuts the screen's detection from 53% to 8% and weakens the cascade, whereas a generic LLM rewrite does not evade the screen, and neither fools the judge. A short decision model explains why: the screen's main value is to raise the base rate the judge sees, a judge with a blind spot is worth little, and a screen whose features are known can lose most of its power.", indent=False, align="justify")
H2(d, "Why we think the work fits the journal")
P(d, "The paper concerns how machine-text detectors should be evaluated and deployed, a question of growing consequence for scientific publishing. It shows that single-generator accuracy can mislead deployment decisions and gives a transparent, countable baseline against which more complex detectors can be judged. We would value your view on whether a paper of this kind, which pairs empirical evaluation with a compact decision model, is in scope.", indent=False, align="justify")
H2(d, "Current state and planned additions")
P(d, "The study is complete for three generators and two judges. Before full submission we plan to add comparisons with published detectors, more and newer generators and fields, and public release of the prompts, generated papers and analysis code. [Edit to reflect the actual state when sent.]", indent=False, align="justify")
d.save("NMI_Presubmission_Enquiry_DRAFT.docx")
